mapper.select:

where r.del_flag = '0'




  and r.enabled = #{q.enabled}


  and r.notify_chat_id = #{q.chatId}


  and r.metric_code = #{q.metricCode}



  and r.owner_user_id = #{q.ownerId}

order by r.rule_no

mapper.update:
update monitor_rule
   set enabled     = #{enabled},
       paused_at = #{pausedAt,jdbcType=TIMESTAMP},
       update_by   = #{updateBy},
       update_time = #{updateTime}
 where rule_id = #{ruleId}
   and site_code = #{scope.siteCode}
   and del_flag = '0'

update monitor_rule
   set del_flag    = '2',
       enabled     = false,
       update_by   = #{updateBy},
       update_time = #{updateTime}
 where rule_id = #{ruleId}
   and site_code = #{scope.siteCode}
   and del_flag = '0'

update monitor_event
   set status      = 'stopped',
       end_hour    = coalesce(last_period_end, #{endHour,jdbcType=TIMESTAMP}),
       stopped_at  = #{now},
       update_time = #{now}
 where rule_id = #{ruleId}
   and site_code = #{scope.siteCode}
   and event_type = 'alert'
   and status = 'open'

mapper.delete:
delete from monitor_rule_state
 where rule_id = #{ruleId}
   and site_code = #{scope.siteCode}
